/** Row-major physical transforms and trilinear compounding, in millimetres. */
export function multiply4(a,b){const out=new Array(16).fill(0);for(let r=0;r<4;r++)for(let c=0;c<4;c++)for(let k=0;k<4;k++)out[r*4+c]+=a[r*4+k]*b[k*4+c];return out;}
export function transformPoint(m,x,y,z=0){return [m[0]*x+m[1]*y+m[2]*z+m[3],m[4]*x+m[5]*y+m[6]*z+m[7],m[8]*x+m[9]*y+m[10]*z+m[11]];}
export function splatPixel(sum,weights,n,x,y,z,p){const ix=Math.floor(x),iy=Math.floor(y),iz=Math.floor(z);const dx=x-ix,dy=y-iy,dz=z-iz;for(let k=0;k<2;k++){const zz=iz+k;if(zz<0||zz>=n)continue;const wz=k?dz:1-dz;for(let j=0;j<2;j++){const yy=iy+j;if(yy<0||yy>=n)continue;const wy=j?dy:1-dy;for(let i=0;i<2;i++){const xx=ix+i;if(xx<0||xx>=n)continue;const w=(i?dx:1-dx)*wy*wz;const q=xx+n*(yy+n*zz);sum[q]+=p*w;weights[q]+=w;}}}}
export function gaussianInPlace(data,n,sigma){if(sigma<.05)return;const radius=Math.ceil(3*sigma);const kernel=[];let total=0;for(let i=-radius;i<=radius;i++){const w=Math.exp(-.5*(i/sigma)**2);kernel.push(w);total+=w;}for(let i=0;i<kernel.length;i++)kernel[i]/=total;let temp=new Float32Array(data.length);for(let axis=0;axis<3;axis++){const stride=axis===0?1:axis===1?n:n*n;for(let z=0;z<n;z++)for(let y=0;y<n;y++)for(let x=0;x<n;x++){const q=x+n*(y+n*z);const coord=axis===0?x:axis===1?y:z;let value=0;for(let k=-radius;k<=radius;k++){if(coord+k>=0&&coord+k<n)value+=data[q+k*stride]*kernel[k+radius];}temp[q]=value;}data.set(temp);} }
export function chooseUniform(length,count){return Array.from({length:count},(_,i)=>Math.round(i*(length-1)/(count-1)));}
